package in.tutorlink.controller; import in.tutorlink.dto.AuthDtos.*; import in.tutorlink.entity.*; import in.tutorlink.repository.*; import in.tutorlink.security.*; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.crypto.password.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final UserRepository users; final PasswordEncoder passwords; final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;}
 @PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.status(409).body(java.util.Map.of("success",false,"message","Email is already registered")); User u=new User();u.fullName=r.fullName();u.email=r.email().toLowerCase();u.password=passwords.encode(r.password());u.role=r.role();u.phone=r.phone();u.location=r.location();users.save(u);return ResponseEntity.status(201).body(new Token(jwt.create(u.id,u.role.name()),u.id,u.fullName,u.role));}
 @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody Login r){var u=users.findByEmail(r.email().toLowerCase()).orElse(null);if(u==null||!passwords.matches(r.password(),u.password))return ResponseEntity.status(401).body(java.util.Map.of("success",false,"message","Invalid email or password"));return ResponseEntity.ok(new Token(jwt.create(u.id,u.role.name()),u.id,u.fullName,u.role));}}
